INSERT INTO public.reception_quiz (mavzu, test_id, question_text, option_text, option_image, is_correct) VALUES ('9-mavzu', '3-test', 'Bron qilingan xonalar soni cheklangan. Bunday vaziyatda reseption xodimi nima qilishi kerak?', 'A) Har qanday holatda ham bronni qabul qilish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/turizm-9/9-3-a.png', false),('9-mavzu', '3-test', 'Bron qilingan xonalar soni cheklangan. Bunday vaziyatda reseption xodimi nima qilishi kerak?', 'B) Mehmonni kutishga majbur qilish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/turizm-9/9-3-b.png', false),('9-mavzu', '3-test', 'Bron qilingan xonalar soni cheklangan. Bunday vaziyatda reseption xodimi nima qilishi kerak?', 'C) Tizimni tekshirib, aniq ma’lumot asosida javob berish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/turizm-9/9-3-c.png', true),('9-mavzu', '3-test', 'Bron qilingan xonalar soni cheklangan. Bunday vaziyatda reseption xodimi nima qilishi kerak?', 'D) Javob bermasdan keyinga qoldirish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/turizm-9/9-3-d.png', false),('9-mavzu', '4-test', 'Mehmon bron ma’lumotlarini o‘zgartirmoqchi. Reseption xodimining to‘g‘ri harakati qaysi?', 'A) O‘zgartirishni e’tiborsiz qoldirish yoki o‘zgarishga yo‘l qo‘ymaslik', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/turizm-9/9-4-a.png', false),('9-mavzu', '4-test', 'Mehmon bron ma’lumotlarini o‘zgartirmoqchi. Reseption xodimining to‘g‘ri harakati qaysi?', 'B) O‘zgarishni tizimga darhol va to‘liq kiritish', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/turizm-9/9-4-b.png', true),('9-mavzu', '4-test', 'Mehmon bron ma’lumotlarini o‘zgartirmoqchi. Reseption xodimining to‘g‘ri harakati qaysi?', 'C) Faqat og‘zaki tasdiqlash', 'https://pub-7038d84e9dec4c259dc08e99c4b5d293.r2.dev/turizm-9/9-4-c.png', false),('9-mavzu', '4-test', 'Mehmon bron ma’lumotlarini o‘zgartirmoqchi. Reseption xodimining to‘g‘ri harakati qaysi?', 'D) Keyinroq kiritishni rejalash', 'https://pub-70